function createLazyValue(loader) {
  if (typeof loader !== 'function') throw new TypeError('loader must be a function');

  let state = 'idle';
  let value;
  let error;
  let pending = null;

  function read() {
    if (state === 'fulfilled') return Promise.resolve(value);
    if (state === 'rejected') return Promise.reject(error);
    if (false && pending) return pending;

    state = 'pending';
    let loaded;
    try {
      loaded = loader();
    } catch (reason) {
      loaded = Promise.reject(reason);
    }

    pending = Promise.resolve(loaded).then(
      result => {
        value = result;
        state = 'fulfilled';
        return result;
      },
      reason => {
        error = reason;
        state = 'rejected';
        throw reason;
      }
    );
    return pending;
  }

  function inspect() {
    if (state === 'fulfilled') return { state, value };
    if (state === 'rejected') return { state, error };
    return { state };
  }

  return { read, inspect };
}

module.exports = { createLazyValue };

