'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api).sort(), ['createLazyValue']);
assert.strictEqual(typeof api.createLazyValue, 'function');
assert.throws(() => api.createLazyValue(), TypeError);
assert.throws(() => api.createLazyValue(42), TypeError);

(async () => {
  let calls = 0;
  let release;
  const sourceValue = { answer: 42 };
  const gate = new Promise(resolve => { release = resolve; });
  const lazy = api.createLazyValue(async () => {
    calls += 1;
    await gate;
    return sourceValue;
  });

  const idleA = lazy.inspect();
  const idleB = lazy.inspect();
  assert.deepStrictEqual(idleA, { state: 'idle' });
  assert.deepStrictEqual(idleB, { state: 'idle' });
  assert.notStrictEqual(idleA, idleB);
  assert.strictEqual(calls, 0);

  const first = lazy.read();
  const second = lazy.read();
  assert.ok(first instanceof Promise);
  assert.strictEqual(first, second);
  assert.strictEqual(calls, 1);
  assert.deepStrictEqual(lazy.inspect(), { state: 'pending' });

  release();
  assert.strictEqual(await first, sourceValue);
  assert.strictEqual(calls, 1);
  const fulfilledA = lazy.inspect();
  const fulfilledB = lazy.inspect();
  assert.deepStrictEqual(fulfilledA, { state: 'fulfilled', value: sourceValue });
  assert.notStrictEqual(fulfilledA, fulfilledB);
  assert.strictEqual(fulfilledA.value, sourceValue);
  assert.deepStrictEqual(sourceValue, { answer: 42 });
  assert.strictEqual(await lazy.read(), sourceValue);
  assert.strictEqual(calls, 1);

  let undefinedCalls = 0;
  const undefinedLazy = api.createLazyValue(() => {
    undefinedCalls += 1;
    return undefined;
  });
  assert.strictEqual(await undefinedLazy.read(), undefined);
  assert.strictEqual(await undefinedLazy.read(), undefined);
  assert.strictEqual(undefinedCalls, 1);
  assert.deepStrictEqual(undefinedLazy.inspect(), {
    state: 'fulfilled', value: undefined
  });

  const failure = new Error('load failed');
  let rejectedCalls = 0;
  const rejectedLazy = api.createLazyValue(() => {
    rejectedCalls += 1;
    return Promise.reject(failure);
  });
  const rejectedPromise = rejectedLazy.read();
  await assert.rejects(rejectedPromise, error => error === failure);
  await assert.rejects(rejectedLazy.read(), error => error === failure);
  assert.strictEqual(rejectedCalls, 1);
  const rejectedState = rejectedLazy.inspect();
  assert.strictEqual(rejectedState.state, 'rejected');
  assert.strictEqual(rejectedState.error, failure);
  assert.strictEqual(failure.message, 'load failed');

  const synchronousFailure = new Error('synchronous');
  const throwingLazy = api.createLazyValue(() => { throw synchronousFailure; });
  let syncPromise;
  assert.doesNotThrow(() => { syncPromise = throwingLazy.read(); });
  assert.ok(syncPromise instanceof Promise);
  await assert.rejects(syncPromise, error => error === synchronousFailure);
})().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

